describe('Table Row Selection', () => {
    beforeEach(() => {
        cy.visit('/your-table-page-url'); // Replace with the actual URL of the page
    });

    it('should select all rows when the header checkbox is checked', () => {
        cy.get('input[type="checkbox"][data-header-checkbox]').check(); // Adjust selector as needed
        cy.get('input[type="checkbox"][data-row-checkbox]').each(($checkbox) => {
            cy.wrap($checkbox).should('be.checked');
        });
    });

    it('should not select any rows when the header checkbox is unchecked', () => {
        cy.get('input[type="checkbox"][data-header-checkbox]').uncheck(); // Adjust selector as needed
        cy.get('input[type="checkbox"][data-row-checkbox]').each(($checkbox) => {
            cy.wrap($checkbox).should('not.be.checked');
        });
    });
});
